package com.greatleyposhley.professy.collaboration;
import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.ObjectMapper;import java.util.*;import java.time.*;import static com.greatleyposhley.professy.collaboration.WorkAccess.number;
/** Explicit invitations protect meeting chat and WebRTC signaling. Agent seats are distinct from human peers. */
@RestController @RequestMapping("/api/workspace/meetings")public class WorkspaceMeetings {
 private final WorkAccess access;private final WorkspaceAgents agents;private final ObjectMapper json;@org.springframework.beans.factory.annotation.Value("${app.meetings.legacy-time-zone:Asia/Kolkata}") private String legacyZone="Asia/Kolkata";public WorkspaceMeetings(WorkAccess access,WorkspaceAgents agents,ObjectMapper json){this.access=access;this.agents=agents;this.json=json;}
 private Map<String,Object> room(long id){access.require("MEETINGS.READ");var actor=access.actor();var rows=access.jdbc.queryForList("SELECT m.*,s.time_zone,s.description,s.revision FROM workspace_meetings m LEFT JOIN workspace_meeting_schedule s ON s.meeting_id=m.id JOIN workspace_meeting_members p ON p.meeting_id=m.id AND p.participant_id=? WHERE m.id=? AND m.org_id=?",actor.getId(),id,actor.getOrgId());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found or you have not been invited");return rows.getFirst();}
 private String text(Object value,int max){String s=Objects.toString(value,"").trim();if(s.length()>max)throw new IllegalArgumentException("Field is too long");return s;}
 private void owner(long id){if(number(room(id).get("owner_id"))!=access.actor().getId())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the organizer can manage this meeting");access.require("MEETINGS.UPDATE");}
 @GetMapping("/config")public Object config(@org.springframework.beans.factory.annotation.Value("${app.meetings.ice-servers:[]}")String configuration){access.require("MEETINGS.READ");return Map.of("iceServers",json.readValue(configuration,List.class),"maxVideoParticipants",8);}
 private Map<String,Object> view(Map<String,Object> row) {
  var result=new LinkedHashMap<>(row);boolean utc=row.get("time_zone")!=null;
  String start=MeetingSchedule.instant(row.get("starts_at"),utc,legacyZone),end=MeetingSchedule.instant(row.get("ends_at"),utc,legacyZone);
  if(start!=null&&end==null)end=Instant.parse(start).plusSeconds(3600).toString();
  result.put("startsAt",start);result.put("starts_at",start);result.put("endsAt",end);result.put("ends_at",end);
  result.put("timeZone",Objects.toString(row.get("time_zone"),legacyZone));
  result.put("description",Objects.toString(row.get("description"),""));result.put("revision",row.get("revision")==null?0:row.get("revision"));
  result.put("editable",number(row.get("owner_id"))==access.actor().getId()&&"SCHEDULED".equals(row.get("status")));
  return result;
 }
 @GetMapping public Object list(@RequestParam(required=false)String from,@RequestParam(required=false)String to) {
  access.require("MEETINGS.READ");boolean calendar=from!=null||to!=null;
  Instant first=calendar?Instant.parse(Objects.requireNonNull(from,"Provide both from and to")):null;
  Instant last=calendar?Instant.parse(Objects.requireNonNull(to,"Provide both from and to")):null;
  if(calendar&&(!last.isAfter(first)||Duration.between(first,last).toDays()>370))throw new IllegalArgumentException("Choose a calendar range up to 370 days");
  String sql="SELECT m.*,s.time_zone,s.description,s.revision,r.response FROM workspace_meetings m LEFT JOIN workspace_meeting_schedule s ON s.meeting_id=m.id JOIN workspace_meeting_members p ON p.meeting_id=m.id LEFT JOIN workspace_meeting_responses r ON r.meeting_id=m.id AND r.participant_id=p.participant_id WHERE m.org_id=? AND p.participant_id=?";
  var args=new ArrayList<Object>(List.of(access.actor().getOrgId(),access.actor().getId()));
  if(calendar){sql+=" AND m.starts_at<? AND COALESCE(m.ends_at,DATE_ADD(m.starts_at,INTERVAL 1 HOUR))>? AND m.status<>'CANCELLED'";args.add(LocalDateTime.ofInstant(last.plusSeconds(64800),ZoneOffset.UTC));args.add(LocalDateTime.ofInstant(first.minusSeconds(64800),ZoneOffset.UTC));}
  else sql+=" ORDER BY COALESCE(m.starts_at,m.created_at) DESC LIMIT 100";
  return access.jdbc.queryForList(sql,args.toArray()).stream().map(this::view).filter(r->!calendar||(r.get("startsAt")!=null&&Instant.parse(r.get("startsAt").toString()).isBefore(last)&&Instant.parse(r.get("endsAt").toString()).isAfter(first))).toList();
 }
 private void schedule(long id,Map<String,Object> body) {
  var dates=MeetingSchedule.parse(body);String title=text(body.get("title"),255);if(title.isBlank())throw new IllegalArgumentException("Give the meeting a title");
  access.jdbc.update("UPDATE workspace_meetings SET title=?,starts_at=?,ends_at=? WHERE id=?",title,dates.start(),dates.end(),id);
  access.jdbc.update("INSERT INTO workspace_meeting_schedule(meeting_id,time_zone,description,revision) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE time_zone=VALUES(time_zone),description=VALUES(description),revision=revision+1",id,dates.zone(),text(body.get("description"),20000));
 }
 @PostMapping @Transactional public Object create(@RequestBody Map<String,Object> body) {
  access.require("MEETINGS.CREATE");access.jdbc.update("INSERT INTO workspace_meetings(org_id,title,owner_id) VALUES(?,?,?)",access.actor().getOrgId(),text(body.get("title"),255),access.actor().getId());
  long id=access.jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);schedule(id,body);
  access.jdbc.update("INSERT INTO workspace_meeting_members(meeting_id,participant_id) VALUES(?,?)",id,access.actor().getId());
  var invitation=new LinkedHashMap<>(body);invitation.putIfAbsent("members",List.of());invite(id,invitation);changed();return get(id);
 }
 private void changed(){access.policy.event(access.actor(),"MEETING_UPDATED",0);}
 @PutMapping("/{id}") @Transactional public Object update(@PathVariable long id,@RequestBody Map<String,Object> body) {
  owner(id);access.jdbc.queryForList("SELECT id FROM workspace_meetings WHERE id=? FOR UPDATE",id);var existing=room(id);
  if(!"SCHEDULED".equals(existing.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only scheduled meetings can be rescheduled");
  if(number(body.get("revision"))!=number(existing.get("revision")))throw new ResponseStatusException(HttpStatus.CONFLICT,"The meeting changed. Reload it before saving");
  schedule(id,body);
  if(body.containsKey("members")){invite(id,body);var keep=new HashSet<Long>();keep.add(access.actor().getId());for(Object v:(List<?>)body.get("members"))keep.add(number(v));for(var member:access.jdbc.queryForList("SELECT participant_id FROM workspace_meeting_members WHERE meeting_id=?",id)){long memberId=number(member.get("participant_id"));if(!keep.contains(memberId)){access.jdbc.update("DELETE FROM workspace_meeting_members WHERE meeting_id=? AND participant_id=?",id,memberId);access.jdbc.update("DELETE FROM workspace_meeting_responses WHERE meeting_id=? AND participant_id=?",id,memberId);}}}
  changed();return get(id);
 }
 @DeleteMapping("/{id}") @Transactional public void cancel(@PathVariable long id) {
  owner(id);int count=access.jdbc.update("UPDATE workspace_meetings SET status='CANCELLED' WHERE id=? AND status='SCHEDULED'",id);
  if(count==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only scheduled meetings can be cancelled");changed();
 }
 @PutMapping("/{id}/response") public Object response(@PathVariable long id,@RequestBody Map<String,Object> body) {
  var meeting=room(id);if("CANCELLED".equals(meeting.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"This meeting was cancelled");
  String response=Objects.toString(body.get("response"),"");if(!Set.of("ACCEPTED","TENTATIVE","DECLINED").contains(response))throw new IllegalArgumentException("Choose a valid response");
  access.jdbc.update("INSERT INTO workspace_meeting_responses(meeting_id,participant_id,response) VALUES(?,?,?) ON DUPLICATE KEY UPDATE response=VALUES(response)",id,access.actor().getId(),response);changed();return get(id);
 }
 @GetMapping("/{id}")public Object get(@PathVariable long id){var result=view(room(id));result.put("participants",participants(id));result.put("messages",access.jdbc.queryForList("SELECT id,author_id AS authorId,body,created_at AS createdAt FROM workspace_meeting_messages WHERE meeting_id=? ORDER BY id DESC LIMIT 200",id));result.put("providerConfigured",false);return result;}
 @PostMapping("/{id}/members")@Transactional public void invite(@PathVariable long id,@RequestBody Map<String,Object> body){owner(id);if(!(body.get("members") instanceof List<?> ids)||ids.size()>50)throw new IllegalArgumentException("Invite up to 50 participants");for(Object value:ids){long participant=number(value);if(participant<0){var agent=agents.row(-participant);if(!"ACTIVE".equals(agent.get("status")))throw new IllegalArgumentException("Choose an active agent");}else if(access.jdbc.queryForObject("SELECT COUNT(*) FROM user_account WHERE id=? AND org_id=? AND is_active=1",Integer.class,participant,access.actor().getOrgId())!=1)throw new IllegalArgumentException("Choose an active person");access.jdbc.update("INSERT IGNORE INTO workspace_meeting_members(meeting_id,participant_id) VALUES(?,?)",id,participant);}changed();}
 private Object participants(long id){return access.jdbc.queryForList("SELECT p.participant_id AS id,COALESCE(r.response,'PENDING') AS response,CASE WHEN p.participant_id<0 THEN a.display_name ELSE CONCAT_WS(' ',u.first_name,u.last_name) END AS name,CASE WHEN p.participant_id<0 THEN 'AGENT' ELSE 'HUMAN' END AS actorType,CASE WHEN p.participant_id<0 THEN ap.designation ELSE u.email END AS subtitle,(p.last_seen>CURRENT_TIMESTAMP-INTERVAL 15 SECOND) AS online,COALESCE(v.audio_enabled,FALSE) AS audioEnabled,COALESCE(v.video_enabled,FALSE) AS videoEnabled,COALESCE(v.screen_sharing,FALSE) AS screenSharing,COALESCE(v.hand_raised,FALSE) AS handRaised FROM workspace_meeting_members p LEFT JOIN workspace_meeting_responses r ON r.meeting_id=p.meeting_id AND r.participant_id=p.participant_id LEFT JOIN workspace_meeting_presence v ON v.meeting_id=p.meeting_id AND v.participant_id=p.participant_id LEFT JOIN user_account u ON u.id=p.participant_id LEFT JOIN workspace_actors a ON a.id=-p.participant_id LEFT JOIN workspace_agent_profiles ap ON ap.actor_id=a.id WHERE p.meeting_id=?",id);}
 @PostMapping("/{id}/join")@Transactional public Object join(@PathVariable long id){var room=room(id);if(Set.of("ENDED","CANCELLED").contains(room.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"This meeting has ended");var locked=access.jdbc.queryForList("SELECT status FROM workspace_meetings WHERE id=? FOR UPDATE",id);if(locked.isEmpty()||Set.of("ENDED","CANCELLED").contains(locked.getFirst().get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"This meeting has ended");if(access.jdbc.queryForObject("SELECT COUNT(*) FROM workspace_meeting_members WHERE meeting_id=? AND participant_id<>? AND last_seen>CURRENT_TIMESTAMP-INTERVAL 15 SECOND",Integer.class,id,access.actor().getId())>=8)throw new ResponseStatusException(HttpStatus.CONFLICT,"This peer-to-peer room supports 8 live participants");access.jdbc.update("UPDATE workspace_meetings SET status='LIVE' WHERE id=?",id);access.jdbc.update("UPDATE workspace_meeting_members SET last_seen=CURRENT_TIMESTAMP(6) WHERE meeting_id=? AND participant_id=?",id,access.actor().getId());return get(id);}
 @PostMapping("/{id}/leave")public void leave(@PathVariable long id){room(id);access.jdbc.update("UPDATE workspace_meeting_members SET last_seen=NULL WHERE meeting_id=? AND participant_id=?",id,access.actor().getId());}
 @PostMapping("/{id}/end")public void end(@PathVariable long id){owner(id);access.jdbc.update("UPDATE workspace_meetings SET status='ENDED' WHERE id=?",id);access.jdbc.update("DELETE FROM workspace_meeting_signals WHERE meeting_id=?",id);access.jdbc.update("DELETE FROM workspace_meeting_agent_sessions WHERE meeting_id=?",id);access.jdbc.update("UPDATE workspace_meeting_members SET last_seen=NULL WHERE meeting_id=?",id);changed();}
 @PostMapping("/{id}/messages")public Object message(@PathVariable long id,@RequestBody Map<String,Object> body){room(id);String message=text(body.get("message"),20000);if(message.isBlank())throw new IllegalArgumentException("Write a message");access.jdbc.update("INSERT INTO workspace_meeting_messages(meeting_id,author_id,body) VALUES(?,?,?)",id,access.actor().getId(),message);return get(id);}
 @GetMapping("/{id}/signals")public Object signals(@PathVariable long id,@RequestParam(defaultValue="0")long after){var room=room(id);if(Set.of("ENDED","CANCELLED").contains(room.get("status")))return Map.of("ended",true,"signals",List.of(),"participants",List.of());access.jdbc.update("UPDATE workspace_meeting_members SET last_seen=CURRENT_TIMESTAMP(6) WHERE meeting_id=? AND participant_id=?",id,access.actor().getId());var signals=access.jdbc.queryForList("SELECT id,sender_id AS senderId,payload FROM workspace_meeting_signals WHERE meeting_id=? AND recipient_id=? AND id>? AND created_at>CURRENT_TIMESTAMP-INTERVAL 2 MINUTE ORDER BY id LIMIT 200",id,access.actor().getId(),after);for(var signal:signals)signal.put("payload",json.readValue(signal.get("payload").toString(),Map.class));return Map.of("signals",signals,"participants",participants(id),"ended",false);}
 @PostMapping("/{id}/signals")public void signal(@PathVariable long id,@RequestBody Map<String,Object> body){room(id);long to=number(body.get("to"));if(to==0||to==access.actor().getId()||access.jdbc.queryForObject("SELECT COUNT(*) FROM workspace_meeting_members WHERE meeting_id=? AND participant_id=?",Integer.class,id,to)!=1)throw new IllegalArgumentException("Select an invited participant in this meeting");if(!(body.get("payload") instanceof Map<?,?> payload)||!Set.of("offer","answer","candidate").contains(payload.get("type")))throw new IllegalArgumentException("Invalid peer signal");String content=text(json.writeValueAsString(payload),50000);access.jdbc.update("INSERT INTO workspace_meeting_signals(meeting_id,sender_id,recipient_id,payload) VALUES(?,?,?,?)",id,access.actor().getId(),to,content);access.jdbc.update("DELETE FROM workspace_meeting_signals WHERE created_at<CURRENT_TIMESTAMP-INTERVAL 3 MINUTE LIMIT 1000");}
 @PostMapping("/{id}/agents/{agent}/reply")public Object agent(@PathVariable long id,@PathVariable long agent,@RequestBody Map<String,Object> body){room(id);if(access.jdbc.queryForObject("SELECT COUNT(*) FROM workspace_meeting_members WHERE meeting_id=? AND participant_id=?",Integer.class,id,-agent)!=1)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Invite this agent first");return agents.reply(agent,body);}
 @PostMapping("/{id}/presence")public void presence(@PathVariable long id,@RequestBody Map<String,Object> body){room(id);access.jdbc.update("INSERT INTO workspace_meeting_presence(meeting_id,participant_id,audio_enabled,video_enabled,screen_sharing,hand_raised) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE audio_enabled=VALUES(audio_enabled),video_enabled=VALUES(video_enabled),screen_sharing=VALUES(screen_sharing),hand_raised=VALUES(hand_raised)",id,access.actor().getId(),Boolean.TRUE.equals(body.get("audioEnabled")),Boolean.TRUE.equals(body.get("videoEnabled")),Boolean.TRUE.equals(body.get("screenSharing")),Boolean.TRUE.equals(body.get("handRaised")));}
 @ExceptionHandler(java.time.format.DateTimeParseException.class)public org.springframework.http.ResponseEntity<?> invalidDate(){return org.springframework.http.ResponseEntity.badRequest().body(Map.of("message","Use an ISO date and time for startsAt and endsAt"));}
}
